from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq


def _temporal(minimum_duration, exact_coupons):
    def solve(data):
        required = data.get("required", [])
        full_mask = (1 << len(required)) - 1
        initial_mask = 0
        for index, node in enumerate(required):
            if node == data["source"]:
                initial_mask |= 1 << index

        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start = data["start"]
        source = data["source"]
        coupons = data["coupons"]
        # The shortest time is tracked independently for every node, visited
        # requirement mask, and number of coupons already spent.
        initial_state = (source, initial_mask, 0)
        best = {initial_state: start}
        queue = [(start, source, initial_mask, 0)]

        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if best.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full_mask
                    and (not exact_coupons or used == coupons)):
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                # close is an exclusive limit on departure, not arrival.
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], used)]
                if used < coupons:
                    discounted = max(minimum_duration,
                                     edge["duration"] - edge.get("discount", 0))
                    choices.append((discounted, used + 1))

                for duration, next_used in choices:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask
                    for index, name in enumerate(required):
                        if name == next_node:
                            next_mask |= 1 << index
                    next_state = (next_node, next_mask, next_used)
                    if next_time < best.get(next_state, float("inf")):
                        best[next_state] = next_time
                        heapq.heappush(queue,
                                       (next_time, next_node, next_mask, next_used))

        return {"arrival": None}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        rank = (event.get("revision", 0), position)
        if event_id not in winners or rank > winners[event_id][0]:
            winners[event_id] = (rank, event)

    rounding = data["rounding"]

    def rounded(numerator):
        if rounding == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = (event.get("account", "default") + "|"
               + event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best_assignment = None
    all_names = sorted(packages, reverse=True)

    def has_cycle(edges):
        state = {}

        def visit(name):
            if state.get(name) == 1:
                return True
            if state.get(name) == 2:
                return False
            state[name] = 1
            for other in edges.get(name, ()):
                if visit(other):
                    return True
            state[name] = 2
            return False

        return any(visit(name) for name in edges if state.get(name, 0) == 0)

    def search(assigned, constraints, edges):
        nonlocal best_vector, best_assignment
        pending = [name for name in constraints if name not in assigned]
        if not pending:
            if has_cycle(edges):
                return
            vector = tuple(assigned[name]["version"] if name in assigned else -1
                           for name in all_names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_assignment = {name: row["version"]
                                   for name, row in assigned.items()}
            return

        name = min(pending)
        ranges = constraints[name]
        rows = sorted(packages.get(name, []), key=lambda row: row["version"])
        for row in rows:
            version = row["version"]
            if any(not low <= version <= high for low, high in ranges):
                continue
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_constraints = {key: list(value)
                                for key, value in constraints.items()}
            next_edges = {key: list(value) for key, value in edges.items()}
            active = []
            for dependency in row.get("deps", []):
                feature = dependency.get("feature", "")
                if feature and feature not in features:
                    continue
                active.append(dependency)
            next_edges[name] = [dependency["name"] for dependency in active]
            valid = True
            for dependency in active:
                other = dependency["name"]
                low, high = dependency["min"], dependency["max"]
                next_constraints.setdefault(other, []).append((low, high))
                if other in next_assigned:
                    other_version = next_assigned[other]["version"]
                    if not low <= other_version <= high:
                        valid = False
                        break
            if valid:
                search(next_assigned, next_constraints, next_edges)

    root_constraints = {name: [tuple(bounds)]
                        for name, bounds in data["roots"].items()}
    search({}, root_constraints, {})
    if best_assignment is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_assignment}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    if mandatory & blocked:
        return {"error": "impossible"}
    options = [job for job in jobs if job["id"] not in blocked]
    by_id = {job["id"]: job for job in options}
    if not mandatory.issubset(by_id) or len(options) < k:
        return {"error": "impossible"}

    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    count = len(options)
    for bits in range(1 << count):
        if bits.bit_count() != k:
            continue
        selected = [options[i] for i in range(count) if bits & (1 << i)]
        ids = sorted(job["id"] for job in selected)
        if not mandatory.issubset(ids):
            continue

        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue

        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value
                or (value == best_value and ids < best_ids)):
            best_value = value
            best_ids = ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": _temporal(2, False),
    "component_02": _temporal(2, True),
    "component_03": _temporal(1, False),
    "component_04": _temporal(1, True),
    "component_05": _temporal(2, False),
    "component_06": _ledger,
    "component_07": _dependencies,
    "component_08": _quota_intervals,
}
